// /portal/beteiligung – Genossenschaft & Energiegemeinschaft für Mitglieder (Fachprüfung Kapitalseite).
// Ehrlicher Stand: Die Genossenschaft ist im Aufbau – nur unverbindliche Vormerkung, keine Zeichnung.

import { HandHeart, Info, Users } from "lucide-react";
import Button from "@/components/ui/Button";
import Begriff from "@/components/Portal/Bedienung/Begriff";
import { Badge, Hinweis, Karte, SeitenKopf } from "@/components/Portal/ui";
import { EgFormular, GenoFormular } from "@/components/Portal/Fach/Beteiligung";
import { portalNutzer, laden } from "@/lib/plattform/server/seite";
import { fachBackend } from "@/lib/plattform/backend/fach";
import { GENO_STATUS } from "@/lib/plattform/fach/mitglied";

export const metadata = { title: "Genossenschaft & Gemeinschaft" };

export default async function BeteiligungSeite() {
  const n = await portalNutzer({ rollen: ["mitglied"] });
  const d = await laden(() => fachBackend().energieDaten(n));
  return (
    <div className="space-y-6">
      <SeitenKopf
        eyebrow="Mitglied"
        titel="Genossenschaft & Energiegemeinschaft"
        text="Beteiligen Sie sich an Solarparks in Ihrer Region und nutzen Sie Strom aus der Nachbarschaft – mit den Stammdaten, die Netzbetreiber dafür verlangen."
        aktionen={<Button href="/genossenschaft" size="sm" variant="ghost" icon={Info}>Mehr zur Genossenschaft</Button>}
      />
      <div className="grid gap-6 xl:grid-cols-2">
        <Karte
          titel={<span className="inline-flex flex-wrap items-center gap-2">Genossenschaft <Badge ton="warn">{GENO_STATUS.text}</Badge></span>}
          untertitel="Unverbindliche Vormerkung – keine Zeichnung, keine Zahlung"
          aktion={<HandHeart aria-hidden="true" className="h-5 w-5 text-ov-600" />}
        >
          <Hinweis ton="warn" className="mb-4">{GENO_STATUS.hinweis} Wir melden uns mit Satzung und Beitrittserklärung, sobald ein Beitritt möglich ist. Mehr zur <Begriff id="energiegenossenschaft">Energiegenossenschaft</Begriff> und zur <Begriff id="nachschusspflicht">Nachschusspflicht</Begriff>.</Hinweis>
          <GenoFormular geno={d.geno} />
        </Karte>
        <Karte titel="Energiegemeinschaft" untertitel="Teilnahme mit Zählpunkt bzw. Marktlokation" aktion={<Users aria-hidden="true" className="h-5 w-5 text-ov-600" />}>
          <p className="mb-4 text-[14px] leading-relaxed text-ink-600">
            Österreich: <Begriff id="eeg-gemeinschaft">Erneuerbare-Energie-Gemeinschaft</Begriff> lokal oder regional bzw. <Begriff id="buergerenergiegemeinschaft">Bürgerenergiegemeinschaft</Begriff> mit <Begriff id="zaehlpunkt">Zählpunktnummer</Begriff>. Deutschland: <Begriff id="energy-sharing">Energy Sharing</Begriff> mit <Begriff id="marktlokation">Marktlokations-ID</Begriff>. Schweiz: <Begriff id="leg">LEG</Begriff> bzw. <Begriff id="zev">ZEV</Begriff>.
          </p>
          <EgFormular eg={d.eg} />
        </Karte>
      </div>
    </div>
  );
}
// /portal/kommune – Gemeinde-Sicht (Fachprüfung Kommunen)
// Eigene kommunale Anliegen; Projekte im Gemeindegebiet erst nach Prüfung durch das Backoffice,
// nur ab Bauleitplanung und nur vereinfacht (keine Eigentümer, Flurstücke oder Pachtkonditionen).
// § 6 EEG als Schätzung – Platzhalter bis zum Finanzmodul.

import Link from "next/link";
import { Building2, Coins, LandPlot, UserRound } from "lucide-react";
import Button from "@/components/ui/Button";
import Begriff from "@/components/Portal/Bedienung/Begriff";
import { Hinweis, Karte, Kennzahl, Leer, SeitenKopf, StatusBadge, Tabelle, zelle } from "@/components/Portal/ui";
import { portalNutzer, laden, istAdmin } from "@/lib/plattform/server/seite";
import { fachBackend } from "@/lib/plattform/backend/kommune";
import { BAULEITPLANUNG_STAND, BUERGERBETEILIGUNG, KOMMUNE_ABSENDER, KOMMUNE_ROLLE, KOMMUNE_SICHTBAR, KOMMUNE_PHASE, KOMMUNE_THEMEN, KRITERIENKATALOG } from "@/lib/plattform/kommune";
import { KOMMUNE } from "@/lib/invest/markt";
import { datum, eur } from "@/lib/plattform/format";
import { LAENDER } from "@/lib/plattform/konstanten";

export const metadata = { title: "Gemeinde" };

const fmtHa = (x) => `${Number(x || 0).toLocaleString("de-DE", { maximumFractionDigits: 1 })} ha`;

function PhasenLeiste({ status }) {
  const i = KOMMUNE_SICHTBAR.indexOf(status);
  return (
    <ol className="flex items-center gap-1" aria-label={`Phase: ${KOMMUNE_PHASE[status] || status}`}>
      {KOMMUNE_SICHTBAR.map((s, j) => (
        <li key={s} className={`h-1.5 w-8 rounded-full ${j <= i ? "bg-ov-500" : "bg-ink-200"}`} title={KOMMUNE_PHASE[s]} />
      ))}
    </ol>
  );
}

export default async function Kommune({ searchParams }) {
  const n = await portalNutzer();
  const sp = (await searchParams) || {};
  const admin = istAdmin(n);
  const vorgangId = admin && typeof sp.vorgang === "string" ? sp.vorgang : undefined;
  const d = await laden(() => fachBackend().kommuneUebersicht(n, { vorgangId }));

  if (admin && !vorgangId) {
    return (
      <div className="space-y-6">
        <SeitenKopf eyebrow="Backoffice · Kommunen" titel="Gemeinde-Sicht" text="Kommunale Anliegen. Die Gemeinde sieht Projekte in ihrem Gebiet erst, wenn Sie das Anliegen als „qualifiziert“ markiert haben – vorher bitte die Gemeinde über einen unabhängigen Weg bestätigen (z. B. Rückruf über die Zentrale der Verwaltung)." />
        <Karte titel="Kommunale Anliegen">
          {d.anliegen.length ? (
            <ul className="divide-y divide-ink-100">
              {d.anliegen.map((a) => (
                <li key={a.id} className="flex flex-wrap items-center justify-between gap-3 py-3">
                  <span className="min-w-0">
                    <span className="font-semibold text-ink-900">{a.gemeinde || "Ohne Gemeindename"}</span>
                    <span className="ml-2 text-[13px] text-ink-500">{a.id} · {LAENDER[a.land] || a.land} · {datum(a.erstelltAm)}</span>
                  </span>
                  <span className="flex items-center gap-3">
                    <StatusBadge art="vorgang" status={a.status} />
                    <Link className="text-[14px] font-semibold text-ov-700 hover:text-ov-800" href={`/portal/kommune?vorgang=${a.id}`}>Sicht der Gemeinde</Link>
                  </span>
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-[14px] text-ink-500">Noch keine kommunalen Anliegen.</p>
          )}
        </Karte>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <SeitenKopf
        eyebrow={admin ? "Backoffice · Sicht der Gemeinde" : "Gemeinde"}
        titel="Solarprojekte in Ihrer Gemeinde"
        text="Vereinfachter Stand der Projekte im Gemeindegebiet, Ihre Anliegen und Ihr Ansprechpartner. Eigentümer- und Vertragsdaten bleiben vertraulich."
        aktionen={admin ? <Button href="/portal/kommune" variant="secondary">Alle Anliegen</Button> : null}
      />

      {!d.anliegen.length && (
        <Leer icon={Building2} titel="Noch kein kommunales Anliegen" text="Stellen Sie Ihre Gemeinde kurz vor – nach einer Prüfung sehen Sie hier die Projekte in Ihrem Gebiet." aktion={<Button href="/kommunen#anfrage">Anliegen schildern</Button>} />
      )}

      {d.anliegen.length > 0 && !d.geprueft && (
        <Hinweis ton="info" titel="Wir prüfen Ihr Anliegen">
          Bevor wir Projektdaten zeigen, bestätigen wir die Gemeinde über einen unabhängigen Weg (in der Regel ein Rückruf über die Verwaltung). Danach erscheinen hier alle Projekte im Gemeindegebiet ab der Bauleitplanung.
        </Hinweis>
      )}

      {d.gemeinden.map((g) => (
        <section key={`${g.name}-${g.land}`} aria-label={`Gemeinde ${g.name}`} className="space-y-4">
          <div className="grid gap-4 sm:grid-cols-3">
            <Kennzahl icon={LandPlot} label={`Projekte in ${g.name}`} wert={String(g.summe.anzahl)} hinweis="ab Bauleitplanung" />
            <Kennzahl icon={LandPlot} label="Fläche zusammen" wert={fmtHa(g.summe.ha)} hinweis="gerundet" />
            <Kennzahl
              icon={Coins}
              label="§ 6 EEG pro Jahr (Schätzung)"
              wert={g.summe.par6EuroProJahr !== null ? eur(g.summe.par6EuroProJahr) : "–"}
              hinweis={g.land === "DE" ? `bis ${String(KOMMUNE.beteiligungCt).replace(".", ",")} ct/kWh ab Inbetriebnahme` : "in AT/CH nicht vorgesehen"}
            />
          </div>

          <Karte titel="Projekte im Gemeindegebiet" untertitel="Vereinfachter Fortschritt – Details stimmen wir im Verfahren mit der Verwaltung ab">
            {g.projekte.length ? (
              <Tabelle kopf={["Nr.", "Art", "Größe", "Phase", "Seit", "§ 6 EEG / Jahr"]}>
                {g.projekte.map((p) => (
                  <tr key={p.nr}>
                    <td className={zelle}>{p.nr}</td>
                    <td className={zelle}>{p.art}</td>
                    <td className={`${zelle} ov-num`}>{fmtHa(p.ha)}</td>
                    <td className={zelle}>
                      <span className="block text-[14px] text-ink-900">{p.phase}</span>
                      <PhasenLeiste status={p.status} />
                    </td>
                    <td className={zelle}>{p.seit ? datum(p.seit) : "–"}</td>
                    <td className={`${zelle} ov-num`}>{p.par6 ? `ca. ${eur(p.par6.euroProJahr)}` : "–"}</td>
                  </tr>
                ))}
              </Tabelle>
            ) : (
              <p className="text-[14px] text-ink-500">Derzeit keine Projekte ab Bauleitplanung in {g.name}.</p>
            )}
            <p className="mt-4 text-[12.5px] leading-relaxed text-ink-500">
              <Begriff id="kommunalbeteiligung">§ 6 EEG</Begriff>: freiwillige Zahlung des Betreibers an die Gemeinde, vertraglich vereinbart, frühestens ab Inbetriebnahme. Die Werte sind grobe Schätzungen aus Fläche und regionalem Ertrag – verbindliche Beträge folgen aus dem Vertrag und den gemessenen Strommengen (Anzeige der Zahlungen folgt mit dem Finanzmodul). Zusätzlich fließen 90 % der Gewerbesteuer der Anlage an die Standortgemeinde.
            </p>
          </Karte>

          {g.ansprechpartner && (
            <Hinweis ton="ok" icon={UserRound} titel="Ihr Ansprechpartner">
              {g.ansprechpartner.vorname} {g.ansprechpartner.nachname} – erreichbar über <Link className="font-semibold underline" href="/portal/nachrichten">Nachrichten</Link>.
            </Hinweis>
          )}
        </section>
      ))}

      {d.anliegen.length > 0 && (
        <Karte titel="Ihre Anliegen">
          <ul className="divide-y divide-ink-100">
            {d.anliegen.map((a) => {
              const x = a.daten || {};
              return (
                <li key={a.id} className="py-3">
                  <div className="flex flex-wrap items-center gap-3">
                    <Link href={`/portal/anfragen/${a.id}`} className="font-semibold text-ov-700 hover:text-ov-800">{a.gemeinde || a.typ}</Link>
                    <StatusBadge art="vorgang" status={a.status} />
                    <span className="text-[13px] text-ink-500">{datum(a.erstelltAm)}</span>
                  </div>
                  <p className="mt-1 text-[13.5px] leading-relaxed text-ink-600">
                    {[
                      KOMMUNE_ABSENDER[x.absender],
                      KOMMUNE_ROLLE[x.rolle],
                      x.bauleitplanung && `Planung: ${BAULEITPLANUNG_STAND[x.bauleitplanung]}`,
                      x.kriterienkatalog && `Kriterienkatalog: ${KRITERIENKATALOG[x.kriterienkatalog]}`,
                      x.interesse6 && `§ 6 EEG: ${x.interesse6 === "ja" ? "Interesse" : x.interesse6 === "nein" ? "kein Interesse" : "offen"}`,
                      x.gemeindeFlaechenHa ? `${fmtHa(x.gemeindeFlaechenHa)} gemeindeeigene Flächen` : "",
                      x.buergerbeteiligung?.length ? `Beteiligung: ${x.buergerbeteiligung.map((b) => BUERGERBETEILIGUNG[b]).filter(Boolean).join(", ")}` : "",
                      x.themen?.length ? `Themen: ${x.themen.map((t) => KOMMUNE_THEMEN[t]).filter(Boolean).join(", ")}` : "",
                    ]
                      .filter(Boolean)
                      .join(" · ")}
                  </p>
                </li>
              );
            })}
          </ul>
        </Karte>
      )}
    </div>
  );
}
// src/lib/plattform/fach/mitglied.js
//
// Mitglieder: Interesse an der Genossenschaft (im Aufbau – keine Zeichnung, nur Vormerkung) und Teilnahme an
// Energiegemeinschaften DE/AT/CH (Stammdaten über energie.js). Reine Funktionen; Frappe: plattform/fach/mitglied.py.
//
// Ehrlicher Stand: Die Genossenschaft ist im Aufbau. Satzung, Höhe des Geschäftsanteils, Mindestbeteiligung und
// Prüfungsverband stehen noch nicht fest – die Plattform nimmt nur unverbindliche Interessenbekundungen entgegen.

import { GEMEINSCHAFTEN } from "../../invest/markt.js";

export const GENO_STATUS = { text: "im Aufbau", hinweis: "Die Genossenschaft ist in Gründung. Eine Beitrittserklärung ist erst nach Eintragung ins Genossenschaftsregister und Aufnahme in einen Prüfungsverband möglich." };
/** Beispielwert eines Geschäftsanteils (markt.js, ausdrücklich Beispiel – Satzung legt fest) */
export const ANTEIL_BEISPIEL_EUR = GEMEINSCHAFTEN.beteiligung.anteilEur;

export const MITGLIED_ARTEN = { privat: "Privatperson", landwirt: "Landwirt / Flächeneigentümer", unternehmen: "Unternehmen", kommune: "Kommune / öffentliche Hand", verein: "Verein / Initiative" };
export const MITGLIED_INTERESSEN = { beteiligung: "Finanzielle Beteiligung an Solarparks", strom: "Strombezug aus eigenen Anlagen (Energiegemeinschaft)", mitwirkung: "Mitwirkung (Generalversammlung, Projekte vor Ort)", flaeche: "Fläche für ein Projekt einbringen" };

/** Rechtliche Hinweise je Land – vorsichtig formuliert, verbindlich ist allein die Satzung */
export const GENO_HINWEISE = {
  DE: [
    { id: "aufbau", titel: "Genossenschaft im Aufbau", text: GENO_STATUS.hinweis },
    { id: "risiko", titel: "Verlustrisiko und Nachschusspflicht", text: "Geschäftsanteile sind eine unternehmerische Beteiligung – im ungünstigsten Fall ist der eingezahlte Betrag verloren. Ob Mitglieder im Insolvenzfall Nachschüsse leisten müssen, legt die Satzung fest (§ 6 Nr. 3 GenG); bei Energiegenossenschaften wird eine Nachschusspflicht üblicherweise ausgeschlossen." },
    { id: "kuendigung", titel: "Kündigung und Auszahlung", text: "Die Mitgliedschaft kann nur zum Schluss eines Geschäftsjahres gekündigt werden, mit mindestens drei Monaten Frist; die Satzung kann eine längere Frist von bis zu fünf Jahren vorsehen (§ 65 GenG). Das Auseinandersetzungsguthaben wird in der Regel binnen sechs Monaten nach dem Ausscheiden auf Basis des Jahresabschlusses ausgezahlt (§ 73 GenG)." },
    { id: "beratung", titel: "Keine Anlageberatung", text: "ÖkoInvest erbringt keine Anlage- oder Steuerberatung. Informationen auf der Plattform ersetzen nicht die Satzung, die Informationen zur Beteiligung und eine persönliche Beratung." },
  ],
  AT: [
    { id: "aufbau", titel: "Genossenschaft im Aufbau", text: "Die Genossenschaft ist in Gründung. Ein Beitritt ist erst nach Eintragung ins Firmenbuch und Aufnahme in einen Revisionsverband möglich." },
    { id: "risiko", titel: "Verlustrisiko und Haftung", text: "Geschäftsanteile können im ungünstigsten Fall verloren gehen. Bei einer Genossenschaft mit beschränkter Haftung haften Mitglieder nach dem österreichischen Genossenschaftsgesetz im Insolvenzfall in der Regel zusätzlich mit einem Betrag in Höhe ihrer Geschäftsanteile, sofern die Satzung nichts anderes bestimmt – bitte die Satzung prüfen." },
    { id: "kuendigung", titel: "Kündigung und Auszahlung", text: "Kündigungsfristen und Auszahlung regelt die Satzung; üblich ist eine Kündigung zum Ende des Geschäftsjahres." },
    { id: "beratung", titel: "Keine Anlageberatung", text: "ÖkoInvest erbringt keine Anlage- oder Steuerberatung." },
  ],
  CH: [
    { id: "aufbau", titel: "Genossenschaft im Aufbau", text: "Die Genossenschaft ist in Gründung. Ein Beitritt ist erst nach Eintragung ins Handelsregister möglich." },
    { id: "risiko", titel: "Verlustrisiko und Haftung", text: "Für Verbindlichkeiten haftet grundsätzlich nur das Genossenschaftsvermögen; die Statuten können eine persönliche Haftung oder Nachschusspflicht vorsehen (Art. 868 ff. OR)." },
    { id: "kuendigung", titel: "Austritt", text: "Ohne abweichende Regelung in den Statuten ist der Austritt nur auf Schluss des Geschäftsjahres mit einjähriger Kündigungsfrist möglich (Art. 844 OR)." },
    { id: "beratung", titel: "Keine Anlageberatung", text: "ÖkoInvest erbringt keine Anlage- oder Steuerberatung." },
  ],
};
export const GENO_BESTAETIGUNGEN = ["aufbau", "risiko", "kuendigung", "beratung"];

class MitgliedFehler extends Error {
  constructor(msg) {
    super(msg);
    this.status = 422;
  }
}

/** Interessenbekundung Genossenschaft bereinigen/prüfen */
export function genoInteresseBereinigen(d = {}) {
  const land = ["DE", "AT", "CH"].includes(d?.land) ? d.land : "DE";
  const anteile = Number.isFinite(Number(d?.anteile)) ? Math.round(Number(d.anteile)) : NaN;
  if (!(anteile >= 1 && anteile <= 1000)) throw new MitgliedFehler("Bitte geben Sie an, wie viele Anteile Sie voraussichtlich zeichnen möchten (1–1.000).");
  const art = Object.prototype.hasOwnProperty.call(MITGLIED_ARTEN, d?.art) ? d.art : "";
  if (!art) throw new MitgliedFehler("Bitte wählen Sie, als wer Sie beitreten möchten.");
  const interessen = Array.isArray(d?.interessen) ? [...new Set(d.interessen.filter((x) => MITGLIED_INTERESSEN[x]))] : [];
  if (!interessen.length) throw new MitgliedFehler("Bitte wählen Sie mindestens ein Interesse.");
  const best = d?.bestaetigt && typeof d.bestaetigt === "object" ? d.bestaetigt : {};
  const fehlt = GENO_BESTAETIGUNGEN.filter((k) => best[k] !== true);
  if (fehlt.length) throw new MitgliedFehler("Bitte bestätigen Sie, dass Sie die Hinweise zur Genossenschaft gelesen haben.");
  return {
    land,
    anteile,
    betragBeispielEur: anteile * ANTEIL_BEISPIEL_EUR,
    art,
    interessen,
    bestaetigt: Object.fromEntries(GENO_BESTAETIGUNGEN.map((k) => [k, true])),
    bemerkung: String(d?.bemerkung ?? "").replace(/[\u0000-\u001F\u007F]/g, " ").trim().slice(0, 500),
  };
}

export { MitgliedFehler };
// PUT /api/portal/fach/mitglied – { art: "geno" | "eg", daten } Interesse Genossenschaft bzw. Teilnahme Energiegemeinschaft
import { route } from "@/lib/plattform/server/route";
import { fachBackend } from "@/lib/plattform/backend/fach";
import { PlattformFehler } from "@/lib/plattform/fehler";

export const PUT = route({ rollen: ["mitglied"] }, async ({ nutzer, body, ip }) => {
  const b = fachBackend();
  if (body.art === "geno") return { ok: true, geno: await b.genoInteresseSpeichern(nutzer, body.daten || {}, { ip }) };
  if (body.art === "eg") return { ok: true, eg: await b.egTeilnahmeSpeichern(nutzer, body.daten || {}) };
  throw new PlattformFehler(422, "Unbekannte Art.");
});
// src/lib/plattform/backend/kommune.js
//
// Backend-Teil „Fachprüfung Flächen & Kommunen“ (eigene Schnittstelle, backend/index.js bleibt unverändert).
// Gleiche Auswahl wie backend(): Frappe bei PLATTFORM_BACKEND=frappe, sonst Demo (503 im Produktions-Build ohne PLATTFORM_DEMO=1).
//
// Operationen (n = angemeldeter Nutzer):
//   kommuneUebersicht(n,{vorgangId}) → { admin, anliegen[], gemeinden[{name, land, schluessel, vorgangId, projekte[], summe, ansprechpartner}], geprueft }
//   fachDemoBereit()                 → ergänzt einmalig Demo-Fachdaten (nur Demo; Frappe: nichts)
//
// Nur serverseitig verwenden.

import * as demo from "./demo/flaecheFach";
import * as frappe from "./frappe/kommune";
import { backendName, KONFIG_FEHLER } from "./index";
import { PlattformFehler } from "../fehler";

export function fachBackend() {
  const n = backendName();
  if (n === "frappe") return frappe;
  if (n === "demo") return demo;
  throw new PlattformFehler(503, KONFIG_FEHLER);
}
// src/lib/plattform/backend/frappe/kommune.js
//
// Frappe-Adapter „Fachprüfung Kommunen“ (Methode oekoinvest_app.plattform.api.kommune.uebersicht).
// Frappe prüft Rolle und Eigentum selbst (als_benutzer) – siehe api/kommune.py.

import { aufruf } from "../frappe";

export async function kommuneUebersicht(n, { vorgangId } = {}) {
  const r = (await aufruf("kommuneUebersicht", { vorgangId: vorgangId || null }, n)) || {};
  return { admin: !!r.admin, anliegen: Array.isArray(r.anliegen) ? r.anliegen : [], gemeinden: Array.isArray(r.gemeinden) ? r.gemeinden : [], geprueft: !!r.geprueft };
}

/** Nur Demo: Demo-Daten ergänzen – in Frappe nichts zu tun */
export async function fachDemoBereit() {}

// src/lib/plattform/backend/fach.js
//
// Backend-Teil „Fachprüfung Kapitalseite“ (eigene Schnittstelle, backend/index.js bleibt unverändert). Auswahl wie
// backend(): Frappe bei PLATTFORM_BACKEND=frappe, sonst Demo (503 im Produktions-Build ohne PLATTFORM_DEMO=1).
// Vertrag: docs/API.md, Abschnitt 11. Datenblatt, LOI und Suchprofil laufen über die bestehenden Operationen
// (projektAendern, statusWechsel, suchprofilSpeichern) – hier nur die neuen Bereiche.
//
// Operationen (n = angemeldeter Nutzer):
//   Energie:    energieDaten(n,{nutzerId?}) · abnahmestelleSpeichern(n,{id?,daten}) · abnahmestelleLoeschen(n,id)
//               lastgangHochladen(n,{name,inhalt,einheit?,abnahmestelleId?,parameter?}) · lastgangNeuRechnen(n,id,parameter)
//               lastgangLoeschen(n,id) · lastgangAnfrage(n,id,{nachricht,ip})
//   Mitglied:   egTeilnahmeSpeichern(n,daten) · genoInteresseSpeichern(n,daten,{ip})
//   Bewertung:  bewertung(n,projektId) · szenarioSpeichern(n,projektId,{name,eingaben}) · szenarioLoeschen(n,id)
//
// Nur serverseitig verwenden.

import * as demo from "./demo/fach";
import * as frappe from "./frappe/fach";
