async function lesenBereit() {
  if (!vorbereitet) {
    // Nachbarmodule einmalig befüllen lassen (eigene Transaktionen, nicht verschachteln)
    await import("./anlagen").then((m) => m.anlagen(SYSTEM)).catch(() => null);
