export function stufe(n, bereich) {
  const zeile = RECHTE_MATRIX[bereich] || RECHTE_MATRIX.sonstiges;
  return unterrollen(n).reduce((m, r) => Math.max(m, zeile[r] ?? 0), 0);
}

