      h.push({ stufe: tage < 120 ? "warnung" : "info", text: `Kündigung spätestens am ${fristIso.split("-").reverse().join(".")} (${tage === 1 ? "1 Tag" : `${tage} Tage`}) – Beschaffung für den Pool rechtzeitig vorbereiten.` });
