 */
export function kommuneDaten(d = {}, land = "DE", kontakt = {}) {
  const x = d && typeof d === "object" ? d : {};
  const l = ["DE", "AT", "CH"].includes(land) ? land : ["DE", "AT", "CH"].includes(x.land) ? x.land : "DE";
  return {
    land: l,
