    gemeindeFlaechenHa: v.zahl(x.gemeindeFlaechenHa, { min: 0, max: 100000, stellen: 1 }),
    interesse6: l === "DE" ? v.auswahl(x.interesse6, ["ja", "nein", "unbekannt"], "") : "",
    buergerbeteiligung: v.mehrfach(x.buergerbeteiligung, BUERGERBETEILIGUNG),
