  return (
    <div className="space-y-6">
      <SeitenKopf
        eyebrow="Mitglied"
        titel="Genossenschaft & Energiegemeinschaft"
        text="Ihre Geschäftsanteile, Generalversammlungen mit Online-Abstimmung und der Strom aus der Nachbarschaft – an einem Ort."
