            {m.uebertragungen.map((u) => <li key={u.id}>Übertragung {u.richtung === "aus" ? "an" : "von"} {u.gegenName}: {u.anteile} Anteile – <strong>{UEBERTRAGUNG_STATUS[u.status]}</strong></li>)}
          </ul>
