	if art not in MATERIAL_VORLAGEN:
		raise fehler("Unbekannte Vorlage.", "art")
	gemeinde, p, angebote = gemeinde or {}, projekt or {}, angebote or []
	g = gemeinde.get("name") or "unserer Gemeinde"
