})
BEREICH = "genossenschaft"
DT_GE, DT_GM, DT_GU, DT_GV, DT_GS, DT_AU = "Plattform Genossenschaft", "Plattform Genossenschaftsmitglied", "Plattform Anteilsuebertragung", "Plattform Generalversammlung", "Plattform GV Stimme", "Plattform Ausschuettung"
