	for x in frappe.get_all(DT_ET, filters={"gemeinschaft": eg["id"], "status": ["in", ["beantragt", "angemeldet", "aktiv"]]}, fields=["daten"], limit_page_length=5000):
		s = (aus_json(x.daten, {}) or {}).get("stamm") or {}
