			konflikt("Dieser Zählpunkt ist in der Gemeinschaft bereits angemeldet.")
	t = {"status": "beantragt", "anteilPct": b["anteilPct"], "beantragtAm": jetzt_iso(), "stamm": stamm, "verlauf": []}
