  pruefe(V.einladungPruefen({ ...gv, status: "entwurf" }, { ...g, land: "DE" }, { heute: H }).frist === 14 && G.einladungsfrist({ land: "CH" }) === 5, "Mindestfrist DE 14 Tage (§ 46 GenG), CH 5 Tage (Art. 882 OR)");
  const gvA = { ...gv, status: "abstimmung" };
